(7478262, 1189053, 10785, '<td valign="top">Reality! Anyone who is married can relate!</td>', 'Reality! Anyone who is married can relate!', '2016-10-13 08:05:59.000000', NULL, 1),
(7478269, 1188967, 140305, '<td valign="top">Spoiled! Looks like a beautiful breakfast :)</td>', 'Spoiled! Looks like a beautiful breakfast :)', '2016-10-13 12:23:34.000000', NULL, 1),
(7478276, 1189041, 140305, '<td valign="top">Beautifully done! Partial desats are difficult to get away with but this is handled perfectly (IMHO) and I love the sweeping feel.  I''m sure this is a photo any bride and groom would be thrilled to have in their wedding album.</td>', 'Beautifully done! Partial desats are difficult to get away with but this is handled perfectly (IMHO) and I love the sweeping feel.  I''m sure this is a photo any bride and groom would be thrilled to have in their wedding album.', '2016-10-13 12:36:30.000000', NULL, 1),
